  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  text: {
    type: "text-content",
    default: "Same script.\nA whole new\ndelivery.",
    description: "Text",
  },
  highlight: {
    type: "text-content",
    default: "delivery.",
    description: "Highlight",
  },
  voiceAt: {
    type: "number",
    default: 28,
    min: 0,
    max: 90,
    step: 1,
    description: "Voice at (frame)",
    hiddenFromList: false,
  },
  stagger: {
    type: "number",
    default: 4,
    min: 0,
    max: 12,
    step: 1,
    description: "Line stagger",
    hiddenFromList: false,
  },
  accent: {
    type: "color",
    default: undefined,
    description: "Accent",
  },
  fontFamily: {
    type: "font-family",
    default: "Inter Tight",
    description: "Font",
  },
  ink: {
    type: "color",
    default: undefined,
    description: "Text color",
  },
  background: {
    type: "color",
    default: undefined,
    description: "Background",
  },
  scale: {
    type: "number",
    default: 1,
    min: 0.5,
    max: 1.5,
    step: 0.05,
    description: "Scale",
