  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","text","highlight","voiceAt","stagger","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  text: "Same script.\nA whole new\ndelivery.",
  highlight: "delivery.",
  voiceAt: 28,
  stagger: 4,
  fontFamily: "Inter Tight",
  scale: 1,
  delay: 0,
  speed: 1,
};

type MonoVoiceElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof MonoVoiceBase>;

const MonoVoiceInner = forwardRef<
  HTMLDivElement,
  MonoVoiceElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<MonoVoice>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <MonoVoiceBase
          {...(componentProps as unknown as ComponentProps<typeof MonoVoiceBase>)}
        />
      </div>
    </Sequence>
  );
});

export const MonoVoice = Interactive.withSchema({
  Component: MonoVoiceInner,
  componentName: "<MonoVoice>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
